questionvariables.text:
/* [low, high, the set where the claim fails, a value where it holds] */
rlist: [[10, 20, {20}, 15], [14, 22, {20, 21, 22}, 17], [37, 45, {37, 38, 39, 40}, 43], [40, 48, {40}, 45], [39, 46, {39, 40}, 44], [17, 24, {20, 21, 22, 23, 24}, 18]];
rpick: rand(rlist);
lo: rpick[1];
hi: rpick[2];
ta1: rpick[3];
ntrue: rpick[4];
/* Diagnostic: equality counted as greater than (the equality points are 20 and 40). */
diag1: setdifference(ta1, {20, 40});
eqpts: intersection(ta1, {20, 40});
eqn: first(listify(eqpts));
lhstrue: dispdp(float(2^(ntrue/10)), 3);
rhstrue: dispdp(float((ntrue/10)^2), 3);
tablerows: makelist([nn, dispdp(float(2^(nn/10)), 3), dispdp(float((nn/10)^2), 3), if is(float(2^(nn/10)) > float((nn/10)^2)) then "yes" else "no"], nn, lo, hi);
/* Validators run with simp:false, where -1 and 6/2 are not yet integers, so simplify first. */
validate_intset(ex) := block([vv], vv: ev(ex, simp), if not(setp(vv)) then "Type a set in curly brackets, for example {5, 6}, or {} for no values."
  else if not(every(integerp, listify(vv))) then "Type whole numbers only." else "");
/* At n = 20 and 40 both sides are exact integers, so the float test is exact there. */
s_assert(is(ta1 = setify(sublist(makelist(nn, nn, lo, hi), lambda([nn], is(float(2^(nn/10)) <= float((nn/10)^2)))))), true);
s_assert(is(length(listify(eqpts)) = 1), true);
